package server

import "net/http"

const dashboard = "<!doctype html>\n<html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Kiwi CI</title>\n<style>\n:root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;color-scheme:dark;--bg:#08110c;--panel:#0d1811;--panel2:#111f16;--line:#203326;--text:#eaf7ee;--muted:#92aa99;--green:#68dc93;--red:#ff7979;--yellow:#f1c866;--blue:#8cb7ff;--purple:#c7a0ff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 10% 0,#102219 0,transparent 28%),var(--bg);color:var(--text)}button,input{font:inherit}header{height:68px;border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 24px;gap:13px;position:sticky;top:0;background:#08110ceB;backdrop-filter:blur(16px);z-index:3}.mark{width:34px;height:34px;border-radius:11px;background:#73e99d;color:#07130b;display:grid;place-items:center;font-weight:900;font-size:20px;box-shadow:0 0 25px #57d98630}.brand{font-weight:800;letter-spacing:-.03em}.subtitle{font-size:12px;color:var(--muted)}.spacer{flex:1}.pill{border:1px solid var(--line);background:var(--panel);border-radius:999px;padding:7px 11px;color:var(--muted);font-size:12px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 0;transition:.2s}.layout.detail{grid-template-columns:minmax(0,1fr) minmax(430px,44vw)}main{padding:24px;max-width:1500px;width:100%;margin:auto}.stats{display:grid;grid-template-columns:repeat(5,minmax(110px,1fr));gap:10px;margin-bottom:20px}.stat{border:1px solid var(--line);background:linear-gradient(160deg,var(--panel2),var(--panel));border-radius:14px;padding:14px}.stat .n{font-size:24px;font-weight:800}.stat .l{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.toolbar{display:flex;align-items:center;gap:10px;margin:14px 0}.toolbar h1{font-size:20px;margin:0;letter-spacing:-.02em}.search{background:var(--panel);border:1px solid var(--line);border-radius:9px;color:var(--text);padding:8px 10px;min-width:220px}.runs{border:1px solid var(--line);border-radius:14px;overflow:hidden;background:var(--panel)}.run{display:grid;grid-template-columns:26px minmax(220px,1.8fr) minmax(130px,1fr) minmax(100px,.7fr) 115px;gap:12px;align-items:center;padding:13px 16px;border-top:1px solid var(--line);cursor:pointer}.run:first-child{border-top:0}.run:hover{background:#15251a}.dot{width:10px;height:10px;border-radius:50%;background:var(--muted)}.success .dot,.dot.success{background:var(--green);box-shadow:0 0 10px #68dc9360}.failure .dot,.blocked .dot,.dot.failure{background:var(--red)}.running .dot,.dot.running{background:var(--yellow);animation:pulse 1.3s infinite}.queued .dot,.waiting_approval .dot,.dot.queued{background:var(--blue)}.cancelled .dot{background:var(--muted)}@keyframes pulse{50%{opacity:.35}}.repo{font-weight:650}.meta{font-size:12px;color:var(--muted);margin-top:3px}.status{font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.04em}.status.success{color:var(--green)}.status.failure,.status.blocked{color:var(--red)}.status.running{color:var(--yellow)}.status.queued,.status.waiting_approval{color:var(--blue)}aside{border-left:1px solid var(--line);height:calc(100vh - 68px);position:sticky;top:68px;overflow:auto;background:#09130d;display:none}.detail aside{display:block}.drawer{padding:20px}.drawer-head{display:flex;gap:10px;align-items:flex-start}.drawer h2{margin:0;font-size:18px}.actions{display:flex;gap:7px;margin:14px 0}.btn{background:var(--panel2);color:var(--text);border:1px solid var(--line);border-radius:8px;padding:7px 10px;cursor:pointer}.btn:hover{border-color:#45634d}.btn.danger{color:#ff9a9a}.btn.primary{color:#83eba5}.section{margin-top:22px}.section-title{font-size:11px;text-transform:uppercase;letter-spacing:.09em;color:var(--muted);margin-bottom:9px}.job{border:1px solid var(--line);border-radius:10px;padding:10px 11px;margin:7px 0;background:var(--panel)}.jobtop{display:flex;gap:8px;align-items:center}.grow{flex:1}.chips{display:flex;gap:5px;flex-wrap:wrap;margin-top:6px}.chip{font-size:10px;padding:3px 6px;border:1px solid var(--line);border-radius:999px;color:var(--muted)}.logs{height:330px;overflow:auto;background:#050a07;border:1px solid var(--line);border-radius:10px;padding:10px;font:11px/1.55 ui-monospace,SFMono-Regular,Menlo,monospace;white-space:pre-wrap}.logline{border-bottom:1px solid #111c15;padding:2px 0}.artifact,.testcard{border:1px solid var(--line);border-radius:9px;padding:9px;margin:6px 0;background:var(--panel);font-size:12px}.muted{color:var(--muted)}.empty{padding:24px;color:var(--muted)}.auth{position:fixed;inset:0;background:#061009ee;display:none;place-items:center;z-index:10}.auth.show{display:grid}.authbox{width:min(420px,90vw);border:1px solid var(--line);background:var(--panel);border-radius:16px;padding:22px}.authbox input{width:100%;margin:12px 0;background:#08110c;border:1px solid var(--line);border-radius:9px;padding:10px;color:var(--text)}@media(max-width:980px){.stats{grid-template-columns:repeat(2,1fr)}.layout.detail{grid-template-columns:1fr}.detail main{display:none}.detail aside{border-left:0}.run{grid-template-columns:20px 1fr 100px}.hide-sm{display:none}}@media(max-width:600px){header,main{padding-left:14px;padding-right:14px}.stats{grid-template-columns:repeat(2,1fr)}.run{padding:12px}.layout.detail aside{position:fixed;inset:68px 0 0;z-index:2}}\n</style></head><body>\n<header><div class=\"mark\">K</div><div><div class=\"brand\">Kiwi CI</div><div class=\"subtitle\">local-first · distributed · explainable</div></div><div class=\"spacer\"></div><div id=\"runnerPill\" class=\"pill\">runners —</div><button class=\"btn\" onclick=\"openAuth()\">Access</button></header>\n<div id=\"layout\" class=\"layout\"><main><div id=\"stats\" class=\"stats\"></div><div class=\"toolbar\"><h1>Runs</h1><div class=\"spacer\"></div><input id=\"runSearch\" class=\"search\" placeholder=\"Filter repository, ref, SHA…\" oninput=\"renderRuns()\"></div><div id=\"runs\" class=\"runs\"><div class=\"empty\">Loading…</div></div></main><aside><div id=\"drawer\" class=\"drawer\"></div></aside></div>\n<div id=\"auth\" class=\"auth\"><div class=\"authbox\"><h2>Kiwi access token</h2><div class=\"muted\">Stored only in this browser session and sent as a Bearer token to the local Kiwi API.</div><input id=\"tokenInput\" type=\"password\" placeholder=\"KIWI_ADMIN_TOKEN\"><div class=\"actions\"><button class=\"btn primary\" onclick=\"saveToken()\">Connect</button><button class=\"btn\" onclick=\"closeAuth()\">Cancel</button></div></div></div>\n<script>\nlet token=sessionStorage.getItem('kiwiToken')||'',runs=[],selected=null,detailTimer=null;\nfunction headers(){return token?{'Authorization':'Bearer '+token}:{}} async function api(path,opt={}){opt.headers={...(opt.headers||{}),...headers()};let r=await fetch(path,opt);if(r.status===401){openAuth();throw new Error('Authentication required')}if(!r.ok)throw new Error(await r.text());let ct=r.headers.get('content-type')||'';return ct.includes('json')?r.json():r.text()}\nfunction esc(x){return String(x??'').replace(/[&<>\\\"]/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[s]))}function fmtTime(x){return x?new Date(x).toLocaleString():'—'}function dur(a,b){if(!a)return'—';let ms=(b?new Date(b):new Date())-new Date(a);if(ms<1000)return ms+'ms';if(ms<60000)return(ms/1000).toFixed(1)+'s';return(ms/60000).toFixed(1)+'m'}function statusClass(s){return esc(s||'queued')}\nfunction openAuth(){document.getElementById('tokenInput').value=token;document.getElementById('auth').classList.add('show')}function closeAuth(){document.getElementById('auth').classList.remove('show')}function saveToken(){token=document.getElementById('tokenInput').value.trim();sessionStorage.setItem('kiwiToken',token);closeAuth();refresh()}\nasync function refresh(){try{let [rs,rr]=await Promise.all([api('/api/v1/runs'),api('/api/v1/runners')]);runs=rs;document.getElementById('runnerPill').textContent=`runners ${rr.filter(x=>x.busy).length}/${rr.length} busy`;renderStats();renderRuns();if(selected)await loadDetail(selected)}catch(e){if(!String(e).includes('Authentication'))console.error(e)}}\nfunction renderStats(){let c={success:0,failure:0,running:0,queued:0,waiting_approval:0};runs.forEach(r=>c[r.status]=(c[r.status]||0)+1);document.getElementById('stats').innerHTML=[['Runs',runs.length],['Passing',c.success],['Running',c.running],['Queued',c.queued],['Needs approval',c.waiting_approval]].map(x=>`<div class=\"stat\"><div class=\"n\">${x[1]}</div><div class=\"l\">${x[0]}</div></div>`).join('')}\nfunction renderRuns(){let q=document.getElementById('runSearch').value.toLowerCase();let xs=runs.filter(r=>JSON.stringify([r.repo_full_name,r.repo,r.ref,r.sha,r.id]).toLowerCase().includes(q));document.getElementById('runs').innerHTML=xs.length?xs.map(r=>`<div class=\"run ${statusClass(r.status)}\" onclick=\"selectRun('${r.id}')\"><div class=\"dot\"></div><div><div class=\"repo\">${esc(r.repo_full_name||r.repo||'API run')}</div><div class=\"meta\"><code>${esc((r.sha||r.id).slice(0,10))}</code> · ${esc(r.event||'manual')}</div></div><div class=\"hide-sm\">${esc(r.ref||'')}</div><div class=\"hide-sm muted\">${fmtTime(r.created_at)}</div><div class=\"status ${statusClass(r.status)}\">${esc(r.status)}</div></div>`).join(''):'<div class=\"empty\">No matching runs.</div>'}\nfunction selectRun(id){selected=id;document.getElementById('layout').classList.add('detail');loadDetail(id);history.replaceState(null,'','?run='+encodeURIComponent(id))}function closeDetail(){selected=null;document.getElementById('layout').classList.remove('detail');history.replaceState(null,'',location.pathname)}\nasync function loadDetail(id){try{let [r,j,l,a,t]=await Promise.all([api('/api/v1/runs/'+id),api('/api/v1/runs/'+id+'/jobs'),api('/api/v1/runs/'+id+'/logs?limit=3000'),api('/api/v1/runs/'+id+'/artifacts'),api('/api/v1/runs/'+id+'/tests')]);let failures=t.reduce((n,x)=>n+x.failures,0),tests=t.reduce((n,x)=>n+x.tests,0);document.getElementById('drawer').innerHTML=`<div class=\"drawer-head\"><div><h2>${esc(r.repo_full_name||r.repo||'Run')}</h2><div class=\"meta\"><code>${esc(r.id)}</code><br>${esc(r.ref||'')} · ${esc(r.sha||'')}</div></div><div class=\"spacer\"></div><button class=\"btn\" onclick=\"closeDetail()\">×</button></div><div class=\"actions\"><button class=\"btn danger\" onclick=\"runAction('cancel','${r.id}')\">Cancel</button><button class=\"btn\" onclick=\"runAction('rerun','${r.id}')\">Rerun</button></div><div class=\"chips\"><span class=\"chip\">${esc(r.status)}</span><span class=\"chip\">${dur(r.started_at,r.finished_at)}</span><span class=\"chip\">${j.length} jobs</span><span class=\"chip\">${tests} tests / ${failures} failed</span></div><div class=\"section\"><div class=\"section-title\">Jobs</div>${renderJobs(j)}</div><div class=\"section\"><div class=\"section-title\">Artifacts</div>${renderArtifacts(a)}</div><div class=\"section\"><div class=\"section-title\">Tests</div>${renderTests(t)}</div><div class=\"section\"><div class=\"toolbar\"><div class=\"section-title\">Logs</div><div class=\"spacer\"></div><input id=\"logSearch\" class=\"search\" placeholder=\"Search logs\" oninput=\"filterLogs()\"></div><div id=\"logs\" class=\"logs\">${renderLogs(l)}</div></div>`;window._logs=l}catch(e){console.error(e)}}\nfunction renderJobs(js){return js.map(j=>`<div class=\"job\"><div class=\"jobtop\"><div class=\"dot ${statusClass(j.status)}\"></div><strong>${esc(j.key)}</strong><div class=\"grow\"></div><span class=\"status ${statusClass(j.status)}\">${esc(j.status)}</span></div><div class=\"chips\">${(j.required_labels||[]).map(x=>`<span class=\"chip\">${esc(x)}</span>`).join('')}${j.environment?`<span class=\"chip\">env: ${esc(j.environment)}</span>`:''}<span class=\"chip\">${j.attempts||0} attempt${j.attempts===1?'':'s'}</span></div>${j.error?`<div class=\"meta\" style=\"color:var(--red);margin-top:7px\">${esc(j.error)}</div>`:''}${j.status==='waiting_approval'?`<button class=\"btn primary\" style=\"margin-top:8px\" onclick=\"approve('${j.id}')\">Approve</button>`:''}</div>`).join('')||'<div class=\"muted\">No jobs</div>'}\nfunction renderArtifacts(a){return a.map(x=>`<div class=\"artifact\"><strong>${esc(x.name)}</strong><div class=\"meta\">${Math.ceil(x.size/1024)} KB · sha256 <code>${esc(x.sha256.slice(0,12))}</code></div><div style=\"margin-top:5px\"><a href=\"#\" onclick=\"downloadArtifact('${x.id}','${esc(x.name)}');return false\">download</a>${x.provenance_sha256?` · <a href=\"#\" onclick=\"downloadProvenance('${x.id}');return false\">provenance</a>`:''}</div></div>`).join('')||'<div class=\"muted\">No artifacts</div>'}\nfunction renderTests(ts){return ts.map(x=>`<div class=\"testcard\"><strong>${esc(x.job_key)}</strong><div class=\"meta\">${x.tests} tests · ${x.failures} failed · ${x.skipped} skipped · ${Number(x.duration_seconds||0).toFixed(2)}s</div></div>`).join('')||'<div class=\"muted\">No structured test reports</div>'}\nfunction renderLogs(ls){return ls.map(x=>`<div class=\"logline\" data-log=\"${esc((x.job_key+' '+x.step+' '+x.line).toLowerCase())}\"><span class=\"muted\">[${esc(x.job_key)}/${esc(x.step)}]</span> ${esc(x.line)}</div>`).join('')||'<span class=\"muted\">No logs yet.</span>'}function filterLogs(){let q=document.getElementById('logSearch').value.toLowerCase();document.querySelectorAll('.logline').forEach(x=>x.style.display=x.dataset.log.includes(q)?'block':'none')}\nasync function runAction(a,id){if(!confirm(a+' this run?'))return;await api('/api/v1/runs/'+id+'/'+a,{method:'POST',headers:{'X-Kiwi-Actor':'dashboard'}});await refresh()}async function approve(id){await api('/api/v1/jobs/'+id+'/approve',{method:'POST',headers:{'X-Kiwi-Actor':'dashboard'}});await refresh()}\nasync function authedBlob(url,name){let r=await fetch(url,{headers:headers()});if(r.status===401){openAuth();return}if(!r.ok){alert(await r.text());return}let b=await r.blob(),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(u)}function downloadArtifact(id,n){authedBlob('/api/v1/artifacts/'+id,n+'.tar.gz')}function downloadProvenance(id){authedBlob('/api/v1/artifacts/'+id+'/provenance',id+'.intoto.json')}\nlet initial=new URLSearchParams(location.search).get('run');if(initial){selected=initial;document.getElementById('layout').classList.add('detail')}if(!token)openAuth();refresh();setInterval(refresh,2500);\n</script></body></html>"

func (s *Server) ui(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Content-Security-Policy", "default-src 'self'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'self'")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Header().Set("Referrer-Policy", "no-referrer")
	_, _ = w.Write([]byte(dashboard))
}
